const contextData = $('Prepare Async Context').first().json;
const startTime = contextData.start_time || Date.now();
const outputFormat = contextData.output_format || 'text';

try {
  let fileContent;

  if (contextData.file_base64) {
    fileContent = contextData.file_base64;
  } else {
    // File was downloaded
    const items = $input.all();
    if (items[0]?.json?.error) {
      return [{
        json: {
          success: false,
          error: {
            code: 500,
            message: 'Failed to download file: ' + (items[0].json.error.message || 'Unknown error'),
            status: 'DOWNLOAD_ERROR'
          },
          meta: { provider: 'docx-extractor' },
          _context: contextData,
          _trace: {
            reasoning: [
              { step: 'extract', result: 'download_error' }
            ],
            model: 'docx-extractor',
            tokens: { input: null, output: null },
            latency_ms: Date.now() - startTime
          }
        }
      }];
    }
    fileContent = items[0]?.binary?.data?.data || '';
  }

  const result = {
    success: true,
    data: {
      content: 'DOCX extraction requires mammoth.js library. Please configure n8n with custom nodes for full DOCX support.',
      format: outputFormat,
      metadata: {
        file_type: 'docx',
        extraction_method: 'placeholder'
      },
      note: 'For production use, install mammoth npm package in n8n custom function node'
    },
    meta: {
      provider: 'docx-extractor',
      output_format: outputFormat
    },
    _context: contextData,
    _trace: {
      reasoning: [
        { step: 'extract', result: 'success' }
      ],
      model: 'docx-extractor',
      tokens: { input: null, output: null },
      latency_ms: Date.now() - startTime
    }
  };

  if (contextData.openai_api_key && contextData.use_vision) {
    result.data.vision_extraction_available = true;
  }

  return [{ json: result }];

} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to extract DOCX: ' + e.message,
        status: 'EXTRACTION_ERROR'
      },
      meta: { provider: 'docx-extractor' },
      _context: contextData,
      _trace: {
        reasoning: [
          { step: 'extract', result: 'extraction_error' }
        ],
        model: 'docx-extractor',
        tokens: { input: null, output: null },
        latency_ms: Date.now() - startTime
      }
    }
  }];
}

