const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET || 'default-secret';

const input = $input.first().json;
const context = input._context || {};

const processingTime = Date.now() - (context.start_time || Date.now());

// Build callback payload without internal context
const { _context, ...resultData } = input;

const callback = {
  job_id: context.job_id,
  status: input.success ? 'completed' : 'failed',
  processing_time_ms: processingTime,
  result: resultData,
  timestamp: new Date().toISOString()
};

const payload = JSON.stringify(callback);
const signature = crypto.createHmac('sha256', secret).update(payload).digest('hex');

return [{
  json: {
    callback_url: context.callback_url,
    payload: callback,
    signature: signature
  }
}];
